function Assert-Exact([string]$Name,$Actual,$Expected){if($null -eq $Actual -and $null -eq $Expected){return};if($null -eq $Actual -or $null -eq $Expected -or $Actual -cne $Expected){throw "Bob Tin progression-frontier $Name differs: expected '$Expected', actual '$Actual'."}}
function Assert-Props([string]$Name,$Object,[string[]]$Expected){if($null -eq $Object){throw "Bob Tin progression-frontier $Name is absent."};$actual=@($Object.PSObject.Properties.Name|Sort-Object);$wanted=@($Expected|Sort-Object);if(($actual -join "`n") -cne ($wanted -join "`n")){throw "Bob Tin progression-frontier $Name properties differ."}}
function Assert-Array([string]$Name,$Actual,[string[]]$Expected){$values=@($Actual|ForEach-Object{[string]$_});if(($values -join "`n") -cne ($Expected -join "`n")){throw "Bob Tin progression-frontier $Name differs."}}
function ConvertTo-CanonicalValue($Value){
  if($null -eq $Value){return $null}
  if($Value -is [System.Collections.IDictionary]){$out=[ordered]@{};foreach($key in @($Value.Keys|ForEach-Object {[string]$_}|Sort-Object)){$out[$key]=ConvertTo-CanonicalValue $Value[$key]};return $out}
  if($Value -is [pscustomobject]){$out=[ordered]@{};foreach($property in @($Value.PSObject.Properties.Name|Sort-Object)){$out[$property]=ConvertTo-CanonicalValue $Value.$property};return $out}
  if($Value -is [System.Collections.IEnumerable] -and -not ($Value -is [string])){return @($Value|ForEach-Object {ConvertTo-CanonicalValue $_})}
  return $Value
}
function ConvertTo-CanonicalJson($Value){return (ConvertTo-CanonicalValue $Value|ConvertTo-Json -Depth 50 -Compress)}
function Assert-Canonical([string]$Name,$Actual,$Expected){if((ConvertTo-CanonicalJson $Actual) -cne (ConvertTo-CanonicalJson $Expected)){throw "Bob Tin progression-frontier $Name differs."}}
function Get-FrontierObservation([string]$Text,[string]$Kind){
  $found=[regex]::Matches($Text,"\[mir-bob-tin-progression-frontier\] $Kind JSON (?<json>\{[^`r`n]+\})")
  if($found.Count -ne 1){throw "Bob Tin progression-frontier requires exactly one $Kind JSON record; observed $($found.Count)."}
  try{return ($found[0].Groups['json'].Value|ConvertFrom-Json -ErrorAction Stop)}catch{throw "Bob Tin progression-frontier $Kind JSON is invalid: $($_.Exception.Message)"}
}
