  if(@($Record.official_mod_closure).Count -ne $expectedOfficialMods.Count){throw 'Bob Tin progression-frontier official closure count differs.'};for($index=0;$index -lt $expectedOfficialMods.Count;$index++){Assert-Props "official_mod_closure[$index]" @($Record.official_mod_closure)[$index] @('name','enabled');Assert-Exact "official_mod_closure[$index].name" @($Record.official_mod_closure)[$index].name $expectedOfficialMods[$index];Assert-Exact "official_mod_closure[$index].enabled" @($Record.official_mod_closure)[$index].enabled $true}
