  Assert-Props anchor $Record.anchor @('stream_key','technology','effect_type','effect_recipe','effect_change_per_completed_level','exact_owner_count','prototype_max_level','prerequisites','science_ingredients','cap_transport');Assert-Exact anchor.stream_key $Record.anchor.stream_key 'research_material_tin';Assert-Exact anchor.technology $Record.anchor.technology 'recipe-prod-research_material_tin-1';Assert-Exact anchor.effect_type $Record.anchor.effect_type 'change-recipe-productivity';Assert-Exact anchor.effect_recipe $Record.anchor.effect_recipe 'bob-tin-plate';Assert-Exact anchor.effect_change $Record.anchor.effect_change_per_completed_level 0.02;Assert-Exact anchor.owner_count $Record.anchor.exact_owner_count 1;Assert-Exact anchor.max_level $Record.anchor.prototype_max_level 'infinite';Assert-Props anchor.cap_transport $Record.anchor.cap_transport @('raw_direct_max_level','mirset1_imported_max_level','effective_max_level');Assert-Exact anchor.cap.raw $Record.anchor.cap_transport.raw_direct_max_level 2;Assert-Exact anchor.cap.imported $Record.anchor.cap_transport.mirset1_imported_max_level 3;Assert-Exact anchor.cap.effective $Record.anchor.cap_transport.effective_max_level 3
  Assert-Props runtime_binding $Record.runtime_binding @('native_infinite_max_level_sentinel','maximum_level_policy_binding_count');Assert-Exact runtime_binding.native_infinite_max_level_sentinel $Record.runtime_binding.native_infinite_max_level_sentinel 4294967295;Assert-Exact runtime_binding.maximum_level_policy_binding_count $Record.runtime_binding.maximum_level_policy_binding_count 1;Assert-Props science_lab_frontier $Record.science_lab_frontier @('candidate_selection_rule','raw_recipe_enabled_semantics','candidate_science_packs','present_non_hidden_lab_prototypes','anchor_compatible_present_non_hidden_lab_ids');Assert-Exact science_lab_frontier.candidate_selection_rule $Record.science_lab_frontier.candidate_selection_rule 'all-final-technology-unit-ingredients-with-exact-item-or-tool-prototype-binding';Assert-Exact science_lab_frontier.raw_recipe_enabled_semantics $Record.science_lab_frontier.raw_recipe_enabled_semantics 'enabled-not-false';foreach($pack in @($Record.science_lab_frontier.candidate_science_packs)){Assert-Props candidate_science_pack $pack @('name','prototype_type','producer_recipe_ids','default_enabled_producer_recipe_ids','direct_unlock_technology_ids');if([string]::IsNullOrWhiteSpace($pack.name) -or $pack.prototype_type -notin @('item','tool')){throw 'Bob Tin progression-frontier candidate technology-unit ingredient identity differs.'}};foreach($lab in @($Record.science_lab_frontier.present_non_hidden_lab_prototypes)){Assert-Props present_non_hidden_lab $lab @('id','inputs');if([string]::IsNullOrWhiteSpace($lab.id)){throw 'Bob Tin progression-frontier present lab identity differs.'}};Assert-Props companion_continuation $Record.companion_continuation @('stable_id_allocation','emission','reason');Assert-Exact companion.stable_id_allocation $Record.companion_continuation.stable_id_allocation 'blocked';Assert-Exact companion.emission $Record.companion_continuation.emission 'blocked';Assert-Exact companion.reason $Record.companion_continuation.reas